#define M0_MIN_HITS   2u      /* 이웃 간격을 재려면 최소 두 발이 있어야 한다 */

/* 스윕 설정. 보고서(키 2) 시작 때 'e' 를 누르면 UART 로 바꾼다 (전원을 끄면 이 기본값으로 돌아온다). */
/* ★ 2026-09-21 : 위상 목록을 고정했다 (사용자 지정, 키 4).
 *   50 / 100 / 150 / 200 / 250 스텝, 각 200발. 한 스텝 = 17.857 ps 이므로
 *   위상 간격 50 스텝 = 892.9 ps 다. 창 밖이 아닌 곳을 고르게 훑으려는 배치다. */
static const u16 M0_PHASES[] = { 50u, 100u, 150u, 200u, 250u };
#define M0_NPH    (u32)(sizeof(M0_PHASES) / sizeof(M0_PHASES[0]))
